{{-- UnoPIM's AJAX navigation imports body styles, not the destination's head.
     Keep this outside Vue's #app in the body stack so both a direct load and
     sidebar/history navigation receive it. Deduplicate shared result renderers. --}}
@pushOnce('scripts', 'dreamlayer-styles')
<style>
.dl-page{max-width:1040px;padding:32px;line-height:1.6;color:inherit}.dl-page h1{font-size:24px;font-weight:600;line-height:1.3}.dl-page h2{font-size:16px;font-weight:600}.dl-page p{margin:0}.dl-stack{display:grid;gap:24px}.dl-section{display:grid;gap:14px;padding:24px 0}.dl-section+.dl-section{border-top:1px solid #e5e7eb}.dark .dl-section+.dl-section{border-color:#3c384c}.dl-heading,.dl-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.dl-actions .primary-button,.dl-actions .secondary-button,.dl-page .primary-button,.dl-page .secondary-button{display:inline-flex;width:auto;flex:none;justify-content:center;align-items:center;min-height:40px;padding:9px 16px;font-size:14px;line-height:20px}.dl-muted{color:#626879;font-size:14px}.dark .dl-muted{color:#b5b2c6}.dl-status-chip{display:inline-flex;align-items:center;border-radius:99px;padding:3px 11px;font-size:12px;font-weight:500;background:#f0eafa;color:#7040ad}.dark .dl-status-chip{background:#3b295a;color:#d7baff}.dl-status-chip.is-connected{background:#e7f5ed;color:#216644}.dark .dl-status-chip.is-connected{background:#1c4033;color:#a3e3c2}.dl-account{display:grid;grid-template-columns:1fr auto;gap:24px;padding:20px;border:1px solid #e5e7eb;border-radius:8px}.dark .dl-account{border-color:#3c384c}.dl-account dt{font-size:12px;color:#626879;margin-bottom:4px}.dark .dl-account dt{color:#b5b2c6}.dl-account dd{font-size:14px;overflow-wrap:anywhere}.dl-account .dl-balance{font-size:22px;font-weight:600}.dl-code{font-size:24px;font-weight:600;letter-spacing:3px;font-family:ui-monospace,monospace}.dl-code-box{display:grid;gap:10px;padding:20px;background:#f7f7fa;border:1px solid #e5e7eb;border-radius:8px}.dark .dl-code-box{background:#242136;border-color:#3c384c}.dl-link{color:#7c3aed;text-decoration:underline;text-underline-offset:3px}.dark .dl-link{color:#b394ff}.dl-error{color:#b42318}.dark .dl-error{color:#ffafa9}.dl-notice{padding:14px 16px;background:#f0f7f3;border-radius:8px;color:#216644}.dark .dl-notice{background:#1c4033;color:#c8edda}.dl-field{display:grid;gap:8px;max-width:620px}.dl-field input,.dl-field select{width:100%;min-height:42px;padding:9px 12px;border:1px solid #b7bac2;border-radius:6px;background:transparent;color:inherit}.dl-field select option{color:#242136;background:#fff}.dl-page summary{cursor:pointer;font-weight:600;padding:8px 0}.dl-page details>div{padding-top:16px}.dl-button-link{border:0;background:transparent;color:inherit;text-decoration:underline;text-underline-offset:3px;padding:8px 0}.dl-danger{color:#b42318}.dark .dl-danger{color:#ffafa9}.dl-page button:disabled{opacity:.5;cursor:not-allowed}.dl-page button:focus-visible,.dl-page a:focus-visible,.dl-page summary:focus-visible{outline:2px solid #9b6bfa;outline-offset:3px}.dl-result-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}.dl-result-card{border:1px solid #dddce4;border-radius:8px;overflow:hidden;padding:16px;display:grid;gap:12px}.dark .dl-result-card{border-color:#3c384c}.dl-result-card img{border-radius:6px}.dl-result-card .primary-button{width:auto}.dl-card-title{font-weight:600;overflow-wrap:anywhere}@media(max-width:640px){.dl-page{padding:20px 16px}.dl-account{grid-template-columns:1fr}.dl-code{font-size:22px}.dl-actions{gap:10px}}
.dl-status-chip.is-pending{background:#fff4d6;color:#795300}.dark .dl-status-chip.is-pending{background:#493b1e;color:#f4d58a}
.dl-workflow{padding:16px!important;line-height:1.6}.dl-workflow>p,.dl-workflow>details{margin-bottom:12px}.dl-workflow .secondary-button,.dl-workflow .primary-button{display:inline-flex;width:auto;padding:8px 14px;font-size:13px;line-height:20px}.dl-workflow .dl-result-action{margin-top:16px}.dl-workflow img{margin-top:16px;margin-bottom:16px}
</style>
@endPushOnce
